<?php $pageTitle='Messages'; require 'config.php'; require 'includes/functions.php'; require_role('student');$uid=user()['id'];
if($_SERVER['REQUEST_METHOD']==='POST'){ $to=(int)$_POST['receiver_id'];$msg=trim($_POST['message']);if($to&&$msg){$pdo->prepare('INSERT INTO messages(sender_id,receiver_id,message) VALUES(?,?,?)')->execute([$uid,$to,$msg]);flash('success','Message sent.');header('Location: messages.php');exit;}}
$users=$pdo->prepare('SELECT id,name,role FROM users WHERE id<>? ORDER BY name');$users->execute([$uid]);$users=$users->fetchAll();$msgs=$pdo->prepare('SELECT m.*,s.name sender_name,r.name receiver_name FROM messages m JOIN users s ON s.id=m.sender_id JOIN users r ON r.id=m.receiver_id WHERE m.sender_id=? OR m.receiver_id=? ORDER BY m.created_at DESC LIMIT 50');$msgs->execute([$uid,$uid]);$msgs=$msgs->fetchAll();include 'includes/header.php';?>
<div class="grid two"><div class="card"><h2>New Message</h2><form method="post"><div class="form-group"><label>Recipient</label><select name="receiver_id"><?php foreach($users as $u):?><option value="<?=$u['id']?>"><?=e($u['name'])?> (<?=e($u['role'])?>)</option><?php endforeach;?></select></div><div class="form-group"><label>Message</label><textarea name="message" required></textarea></div><button class="btn">Send</button></form></div><div><h2>Recent Messages</h2><?php foreach($msgs as $m):?><div class="card" style="margin-bottom:12px"><small class="muted"><?=e($m['sender_name'])?> → <?=e($m['receiver_name'])?> • <?=e($m['created_at'])?></small><p><?=e($m['message'])?></p></div><?php endforeach;?></div></div>
<?php include 'includes/footer.php'; ?>
